// ------------------------------------------------------------------ the clock
function cronMatch(f, v) {
  return f.split(",").some(p => { if (p === "*") return true; const [r, st] = p.split("/"), step = +st || 1;
    const [lo, hi] = r === "*" ? [0, 99] : r.includes("-") ? r.split("-").map(Number) : [+r, st ? 99 : +r];
    return v >= lo && v <= hi && (v - lo) % step === 0; });
}
